import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import './googlemap.css';

const Map = () => {
    const location = useLocation();
    const { lat, lng } = location.state || {};

    useEffect(() => {
        const initMap = () => {
            const defaultLocation = { lat: 32.1, lng: 35.4 };
            const mapLocation = lat && lng ? { lat, lng } : defaultLocation;

            const map = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 12,
                center: mapLocation,
            });

            if (lat && lng) {
                new window.google.maps.Marker({
                    position: mapLocation,
                    map: map,
                    title: 'Pet Location',
                });
            }

            const directionsService = new window.google.maps.DirectionsService();
            const directionsRenderer = new window.google.maps.DirectionsRenderer();
            directionsRenderer.setMap(map);

            const calculateAndDisplayRoute = (directionsService, directionsRenderer, start, end) => {
                directionsService.route(
                    {
                        origin: start,
                        destination: end,
                        travelMode: 'DRIVING', // ניתן לשנות ל-'WALKING', 'BICYCLING', או 'TRANSIT'
                    },
                    (response, status) => {
                        if (status === 'OK') {
                            directionsRenderer.setDirections(response);
                        } else {
                            console.error('Directions request failed due to ' + status);
                        }
                    }
                );
            };

            if (lat && lng) {
                if (navigator.geolocation) {
                    navigator.geolocation.getCurrentPosition(
                        (position) => {
                            const start = {
                                lat: position.coords.latitude,
                                lng: position.coords.longitude,
                            };
                            const end = mapLocation;
                            calculateAndDisplayRoute(directionsService, directionsRenderer, start, end);
                        },
                        () => {
                            console.error('Error fetching current position');
                        }
                    );
                } else {
                    console.error('Geolocation not supported');
                }
            }
        };

        if (!window.google) {
            window.initMap = initMap;

            const script = document.createElement('script');
            script.src = `https://maps.googleapis.com/maps/api/js?AIzaSyAyCujJ188OdhtBjKLmV2CheQgDnqEa-9o&callback=initMap`;
            script.async = true;
            script.defer = true;
            document.head.appendChild(script);

            return () => {
                document.head.removeChild(script);
                delete window.initMap;
            };
        } else {
            initMap();
        }
    }, [lat, lng]);

    return (
        <div className="container">
            <div id="map" style={{ height: '400px', width: '100%' }}></div>
        </div>
    );
};

export default Map;
